import CryptoKit
import Foundation
import Testing

/// Golden cases and Node's expected responses, generated by
/// `pnpm -C apps/studio-ios golden` and copied into this test bundle.
struct GoldenCases {
    struct Case: Decodable, Sendable {
        let name: String
        let operation: String
        let input: String
    }

    struct Summary: Decodable, Sendable {
        let cases: Int
        let engineSha256: String
    }

    let cases: [Case]
    let expected: [String: String]
    let summary: Summary

    static func load() throws -> GoldenCases {
        let directory = try #require(
            Bundle.module.url(forResource: "Golden", withExtension: nil),
            "Golden cases are missing; run `pnpm -C apps/studio-ios build:engine && pnpm -C apps/studio-ios golden`."
        )
        let decoder = JSONDecoder()
        let cases = try decoder.decode([Case].self, from: Data(contentsOf: directory.appending(path: "cases.json")))
        let expected = try decoder.decode([String: String].self, from: Data(contentsOf: directory.appending(path: "expected.json")))
        let summary = try decoder.decode(Summary.self, from: Data(contentsOf: directory.appending(path: "summary.json")))
        try #require(cases.count == summary.cases, "cases.json and summary.json disagree; regenerate the golden files.")
        return GoldenCases(cases: cases, expected: expected, summary: summary)
    }

    static func sha256(of url: URL) throws -> String {
        SHA256.hash(data: try Data(contentsOf: url)).map { String(format: "%02x", $0) }.joined()
    }
}
